"""Customer insight endpoints for the account team."""

from __future__ import annotations

from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int


class CustomerInsightsController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with the totals the order summary reports."""
        try:
            summaries = self._service.order_history(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {
            "customer_id": customer_id,
            "orders": [{"order_id": s.order.order_id, "status": s.order.status,
                        "total_cents": s.total_cents} for s in summaries],
        })

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Count of a customer's non-cancelled orders and the sum of their totals."""
        try:
            order_count, lifetime_value_cents = self._service.lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id, "order_count": order_count,
                              "lifetime_value_cents": lifetime_value_cents})

    def handle_top_customers(self, limit: Any) -> Response:
        """Customers with the highest lifetime value, at most ``limit`` of them."""
        try:
            limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        rows = self._service.top_customers(limit)
        return Response(200, {"customers": [
            {"customer_id": customer_id, "name": name, "lifetime_value_cents": value}
            for customer_id, name, value in rows
        ]})

def place(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_order_history_for_unknown_customer_is_not_found(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_order_history_is_empty_for_customer_without_orders(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_order_history_lists_newest_order_first(shop):
    first = place(shop, "c1", ("BOOK", 1)).body["order_id"]
    place(shop, "c2", ("PEN", 1))
    second = place(shop, "c1", ("PEN", 2)).body["order_id"]
    body = shop.insights.handle_order_history("c1").body
    assert [o["order_id"] for o in body["orders"]] == [second, first]


def test_order_history_reports_order_summary_total_including_discount(shop):
    oid = place(shop, "c2", ("LAMP", 2)).body["order_id"]
    summary_total = shop.orders.handle_get(oid).body["total_cents"]
    entry = shop.insights.handle_order_history("c2").body["orders"][0]
    assert entry == {"order_id": oid, "status": "placed", "total_cents": summary_total}
    assert entry["total_cents"] == 10200


def test_order_history_includes_cancelled_orders_with_their_status(shop):
    oid = place(shop, "c1", ("PEN", 3)).body["order_id"]
    shop.orders.handle_cancel(oid)
    body = shop.insights.handle_order_history("c1").body
    assert body["orders"] == [{"order_id": oid, "status": "cancelled", "total_cents": 900}]


def test_lifetime_value_for_unknown_customer_is_not_found(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_is_zero_for_customer_without_orders(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_sums_order_totals_including_discount(shop):
    place(shop, "c2", ("LAMP", 2))
    place(shop, "c2", ("PEN", 1))
    body = shop.insights.handle_lifetime_value("c2").body
    assert body == {"customer_id": "c2", "order_count": 2, "lifetime_value_cents": 10200 + 300}


def test_lifetime_value_excludes_cancelled_orders(shop):
    place(shop, "c1", ("BOOK", 1))
    cancelled = place(shop, "c1", ("PEN", 3)).body["order_id"]
    shop.orders.handle_cancel(cancelled)
    body = shop.insights.handle_lifetime_value("c1").body
    assert body == {"customer_id": "c1", "order_count": 1, "lifetime_value_cents": 2500}


def test_top_customers_rejects_limit_that_is_not_a_positive_integer(shop):
    for limit in (0, -1, True, "3", None, 2.0):
        response = shop.insights.handle_top_customers(limit)
        assert response.status == 400
        assert "limit" in response.body["error"]


def test_top_customers_is_empty_when_nobody_has_ordered(shop):
    assert shop.insights.handle_top_customers(5).body == {"customers": []}


def test_top_customers_ranks_by_lifetime_value_then_customer_id(shop):
    place(shop, "c1", ("BOOK", 1))
    place(shop, "c2", ("BOOK", 1))
    place(shop, "c2", ("PEN", 1))
    body = shop.insights.handle_top_customers(10).body
    assert body == {"customers": [
        {"customer_id": "c2", "name": "Grace", "lifetime_value_cents": 2800},
        {"customer_id": "c1", "name": "Ada", "lifetime_value_cents": 2500},
    ]}


def test_top_customers_breaks_ties_by_customer_id(shop):
    place(shop, "c2", ("BOOK", 1))
    place(shop, "c1", ("BOOK", 1))
    ids = [row["customer_id"] for row in shop.insights.handle_top_customers(10).body["customers"]]
    assert ids == ["c1", "c2"]


